// Mission text translation: everything the scripted missions show is registered source English (src/i18n/en/
// missions.ts, generated by tools/i18n/mission-text.ts, plus the cast, tutorial, modes and Conquest modules), so the
// screens can translate it; tests/i18n.test.ts then checks every registered key is translated in every language.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { unregisteredMissionText } from '../tools/i18n/mission-text';
import { loadLocale, OTHER_LANGS } from '../tools/i18n/lib';
import { isSourceText, registerLocale, setLanguage, trSource } from '../src/i18n/core';
import { MISSIONS } from '../src/missions';

describe('mission text is translatable', () => {
  test('every text the mission scripts show is registered source English', async () => {
    const bad = await unregisteredMissionText();
    assert.deepEqual(bad.map((f) => `${f.file}:${f.line} ${f.text}`), [], 'mission text nothing registers: run node --import tsx tools/i18n/mission-text.ts and translate the new keys');
  });
  test('briefings, tips, debriefs and objectives of every mission translate', async () => {
    const texts = new Set<string>();
    // (the Daily Challenge's generated briefing is never shown: the challenge screen writes its own, translated)
    for (const m of Object.values(MISSIONS).filter((d) => d.id !== 'daily')) {
      for (const t of [...(m.briefing ?? []), ...(m.tips ?? [])]) texts.add(t);
      const d = (m as { debrief?: { win?: string; lose?: string } }).debrief;
      if (d?.win) texts.add(d.win);
      if (d?.lose) texts.add(d.lose);
    }
    const missing = [...texts].filter((t) => !isSourceText(t));
    assert.deepEqual(missing, [], 'mission briefing text that is not registered');
    for (const l of OTHER_LANGS) {
      registerLocale(l, loadLocale(l));
      await setLanguage(l);
      const same = [...texts].filter((t) => trSource(t) === t);
      assert.deepEqual(same, [], `${l}: mission text shown in English`);
    }
    await setLanguage('auto');
  });
});
